questionvariables.text:
aa:rand_with_prohib(5,13,[6]);

/*model solution*/
first_num:floor(((1/3)*aa)+1);
sec_num:aa
third_num:aa
fifth_num:aa+first_num;
fourth_num:(5*aa) - (first_num+sec_num+third_num+fifth_num);

ta_list:sort([first_num,sec_num,third_num,fourth_num,fifth_num]);


/*   ------------------   Mode function   ---------------------   */
/*  mode(n) returns a list of all the modal elements in the list n */

mode(n):=block([i,j,count_elements,counts,highest_count,mode_set],count_elements:makelist(0,i,1,length(n)),for i:1 thru length(n) do (for j:1 thru length(n) do(if n[i]=n[j] then count_elements[i]:count_elements[i]+1)),counts:listify(setify(count_elements)),highest_count:counts[length(counts)],mode_set:{},for i:1 thru length(n) do (if count_elements[i]=highest_count then mode_set:union(mode_set,{n[i]})),mode_set:listify(mode_set),return(mode_set));

/* --------------------------------------------------------------------------------- */

feedbackvariables.text:
ans_list:[ans1,ans2,ans3,ans4,ans5];
ans_list:sort(ans_list);

ans_mean:mean(ans_list);
ans_median:median(ans_list);
ans_range:range(ans_list);
ans_mode:mode(ans_list)[1];

Sans_mn: if ans_mean=aa then 1 else 0;
Sans_med: if ans_median=aa then 1 else 0;
Sans_range: if ans_range=aa then 1 else 0;
Sans_mode: if ans_mode=aa then 1 else 0;

Sans_mn_feedback:if Sans_mn=1 then "which is correct." else "which is incorrect."
Sans_med_feedback:if Sans_med=1 then "which is correct." else "which is incorrect."
Sans_range_feedback:if Sans_range=1 then "which is correct." else "which is incorrect."
Sans_mode_feedback:if Sans_mode=1 then "which is correct." else "which is incorrect."

/*all 4 equal*/
ta:Sans_mn*Sans_med*Sans_range*Sans_mode; 

/* check how many are correct (ie equal to aa) */
answer_check_list:[ans_mean,ans_median,if length(mode(ans_list))>1 then 0.001 else ans_mode,ans_range];
number_correct:0
for i:1 thru 4 do (if answer_check_list[i]=aa then number_correct:number_correct+1);

/* Check if all are equal */
all_equal:if cardinality({ans_mean,ans_median,ans_mode,ans_range})=1 then 1 else 0;
